insert into public.legal_provisions (
    version_id, provision_key, sequence, heading_path, heading, label, content
)
select
    '21000000-0000-4000-8000-000000000014', item.chave, item.sequencia, item.caminho, item.titulo, item.rotulo, item.conteudo
from jsonb_to_recordset($dados$[{"chave":"art-1","sequencia":1,"caminho":["LEI DE DROGAS","TÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"TÍTULO I — DISPOSIÇÕES PRELIMINARES","rotulo":"Art. 1º","conteudo":"Esta Lei institui o Sistema Nacional de Políticas Públicas sobre Drogas - Sisnad; prescreve medidas para prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas; estabelece normas para repressão à produção não autorizada e ao tráfico ilícito de drogas e define crimes.\n\nParágrafo único. Para fins desta Lei, consideram-se como drogas as substâncias ou os produtos capazes de causar dependência, assim especificados em lei ou relacionados em listas atualizadas periodicamente pelo Poder Executivo da União."},{"chave":"art-2","sequencia":2,"caminho":["LEI DE DROGAS","TÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"TÍTULO I — DISPOSIÇÕES PRELIMINARES","rotulo":"Art. 2º","conteudo":"Ficam proibidas, em todo o território nacional, as drogas, bem como o plantio, a cultura, a colheita e a exploração de vegetais e substratos dos quais possam ser extraídas ou produzidas drogas, ressalvada a hipótese de autorização legal ou regulamentar, bem como o que estabelece a Convenção de Viena, das Nações Unidas, sobre Substâncias Psicotrópicas, de 1971, a respeito de plantas de uso estritamente ritualístico-religioso.\n\nParágrafo único. Pode a União autorizar o plantio, a cultura e a colheita dos vegetais referidos no caput deste artigo, exclusivamente para fins medicinais ou científicos, em local e prazo predeterminados, mediante fiscalização, respeitadas as ressalvas supramencionadas."},{"chave":"art-3","sequencia":3,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS"],"titulo":"TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","rotulo":"Art. 3º","conteudo":"O Sisnad tem a finalidade de articular, integrar, organizar e coordenar as atividades relacionadas com:\n\nI - a prevenção do uso indevido, a atenção e a reinserção social de usuários e dependentes de drogas;\n\nII - a repressão da produção não autorizada e do tráfico ilícito de drogas.\n\n§ 1º Entende-se por Sisnad o conjunto ordenado de princípios, regras, critérios e recursos materiais e humanos que envolvem as políticas, planos, programas, ações e projetos sobre drogas, incluindo-se nele, por adesão, os Sistemas de Políticas Públicas sobre Drogas dos Estados, Distrito Federal e Municípios. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 2º O Sisnad atuará em articulação com o Sistema Único de Saúde - SUS, e com o Sistema Único de Assistência Social - SUAS. (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-4","sequencia":4,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO I — DOS PRINCÍPIOS E DOS OBJETIVOS DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS"],"titulo":"CAPÍTULO I — DOS PRINCÍPIOS E DOS OBJETIVOS DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","rotulo":"Art. 4º","conteudo":"São princípios do Sisnad:\n\nI - o respeito aos direitos fundamentais da pessoa humana, especialmente quanto à sua autonomia e à sua liberdade;\n\nII - o respeito à diversidade e às especificidades populacionais existentes;\n\nIII - a promoção dos valores éticos, culturais e de cidadania do povo brasileiro, reconhecendo-os como fatores de proteção para o uso indevido de drogas e outros comportamentos correlacionados;\n\nIV - a promoção de consensos nacionais, de ampla participação social, para o estabelecimento dos fundamentos e estratégias do Sisnad;\n\nV - a promoção da responsabilidade compartilhada entre Estado e Sociedade, reconhecendo a importância da participação social nas atividades do Sisnad;\n\nVI - o reconhecimento da intersetorialidade dos fatores correlacionados com o uso indevido de drogas, com a sua produção não autorizada e o seu tráfico ilícito;\n\nVII - a integração das estratégias nacionais e internacionais de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao seu tráfico ilícito;\n\nVIII - a articulação com os órgãos do Ministério Público e dos Poderes Legislativo e Judiciário visando à cooperação mútua nas atividades do Sisnad;\n\nIX - a adoção de abordagem multidisciplinar que reconheça a interdependência e a natureza complementar das atividades de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas, repressão da produção não autorizada e do tráfico ilícito de drogas;\n\nX - a observância do equilíbrio entre as atividades de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao seu tráfico ilícito, visando a garantir a estabilidade e o bem-estar social;\n\nXI - a observância às orientações e normas emanadas do Conselho Nacional Antidrogas - Conad."},{"chave":"art-5","sequencia":5,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO I — DOS PRINCÍPIOS E DOS OBJETIVOS DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS"],"titulo":"CAPÍTULO I — DOS PRINCÍPIOS E DOS OBJETIVOS DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","rotulo":"Art. 5º","conteudo":"O Sisnad tem os seguintes objetivos:\n\nI - contribuir para a inclusão social do cidadão, visando a torná-lo menos vulnerável a assumir comportamentos de risco para o uso indevido de drogas, seu tráfico ilícito e outros comportamentos correlacionados;\n\nII - promover a construção e a socialização do conhecimento sobre drogas no país;\n\nIII - promover a integração entre as políticas de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao tráfico ilícito e as políticas públicas setoriais dos órgãos do Poder Executivo da União, Distrito Federal, Estados e Municípios;\n\nIV - assegurar as condições para a coordenação, a integração e a articulação das atividades de que trata o art. 3º desta Lei."},{"chave":"art-6","sequencia":6,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","SEÇÃO I — DA COMPOSIÇÃO DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS"],"titulo":"SEÇÃO I — DA COMPOSIÇÃO DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","rotulo":"Art. 6º","conteudo":"(VETADO)"},{"chave":"art-7","sequencia":7,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","SEÇÃO I — DA COMPOSIÇÃO DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS"],"titulo":"SEÇÃO I — DA COMPOSIÇÃO DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","rotulo":"Art. 7º","conteudo":"A organização do Sisnad assegura a orientação central e a execução descentralizada das atividades realizadas em seu âmbito, nas esferas federal, distrital, estadual e municipal e se constitui matéria definida no regulamento desta Lei."},{"chave":"art-7-a","sequencia":8,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","SEÇÃO I — DA COMPOSIÇÃO DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS"],"titulo":"SEÇÃO I — DA COMPOSIÇÃO DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","rotulo":"Art. 7º-A","conteudo":"(VETADO). (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-8","sequencia":9,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","SEÇÃO I — DA COMPOSIÇÃO DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS"],"titulo":"SEÇÃO I — DA COMPOSIÇÃO DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","rotulo":"Art. 8º","conteudo":"(VETADO)"},{"chave":"art-8-a","sequencia":10,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","SEÇÃO II — DAS COMPETÊNCIAS"],"titulo":"SEÇÃO II — DAS COMPETÊNCIAS","rotulo":"Art. 8º-A","conteudo":"Compete à União: (Incluído pela Lei nº 13.840, de 2019)\n\nI - formular e coordenar a execução da Política Nacional sobre Drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nII - elaborar o Plano Nacional de Políticas sobre Drogas, em parceria com Estados, Distrito Federal, Municípios e a sociedade; (Incluído pela Lei nº 13.840, de 2019)\n\nIII - coordenar o Sisnad; (Incluído pela Lei nº 13.840, de 2019)\n\nIV - estabelecer diretrizes sobre a organização e funcionamento do Sisnad e suas normas de referência; (Incluído pela Lei nº 13.840, de 2019)\n\nV - elaborar objetivos, ações estratégicas, metas, prioridades, indicadores e definir formas de financiamento e gestão das políticas sobre drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nVI – (VETADO); (Incluído pela Lei nº 13.840, de 2019)\n\nVII – (VETADO); (Incluído pela Lei nº 13.840, de 2019)\n\nVIII - promover a integração das políticas sobre drogas com os Estados, o Distrito Federal e os Municípios; (Incluído pela Lei nº 13.840, de 2019)\n\nIX - financiar, com Estados, Distrito Federal e Municípios, a execução das políticas sobre drogas, observadas as obrigações dos integrantes do Sisnad; (Incluído pela Lei nº 13.840, de 2019)\n\nX - estabelecer formas de colaboração com Estados, Distrito Federal e Municípios para a execução das políticas sobre drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nXI - garantir publicidade de dados e informações sobre repasses de recursos para financiamento das políticas sobre drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nXII - sistematizar e divulgar os dados estatísticos nacionais de prevenção, tratamento, acolhimento, reinserção social e econômica e repressão ao tráfico ilícito de drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nXIII - adotar medidas de enfretamento aos crimes transfronteiriços; e (Incluído pela Lei nº 13.840, de 2019)\n\nXIV - estabelecer uma política nacional de controle de fronteiras, visando a coibir o ingresso de drogas no País. (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-8-b","sequencia":11,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","SEÇÃO II — DAS COMPETÊNCIAS"],"titulo":"SEÇÃO II — DAS COMPETÊNCIAS","rotulo":"Art. 8º-B","conteudo":"(VETADO). (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-8-c","sequencia":12,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","SEÇÃO II — DAS COMPETÊNCIAS"],"titulo":"SEÇÃO II — DAS COMPETÊNCIAS","rotulo":"Art. 8º-C","conteudo":"(VETADO). (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-8-d","sequencia":13,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO II-A","SEÇÃO I — DO PLANO NACIONAL DE POLÍTICAS SOBRE DROGAS"],"titulo":"SEÇÃO I — DO PLANO NACIONAL DE POLÍTICAS SOBRE DROGAS","rotulo":"Art. 8º-D","conteudo":"São objetivos do Plano Nacional de Políticas sobre Drogas, dentre outros: (Incluído pela Lei nº 13.840, de 2019)\n\nI - promover a interdisciplinaridade e integração dos programas, ações, atividades e projetos dos órgãos e entidades públicas e privadas nas áreas de saúde, educação, trabalho, assistência social, previdência social, habitação, cultura, desporto e lazer, visando à prevenção do uso de drogas, atenção e reinserção social dos usuários ou dependentes de drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nII - viabilizar a ampla participação social na formulação, implementação e avaliação das políticas sobre drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nIII - priorizar programas, ações, atividades e projetos articulados com os estabelecimentos de ensino, com a sociedade e com a família para a prevenção do uso de drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nIV - ampliar as alternativas de inserção social e econômica do usuário ou dependente de drogas, promovendo programas que priorizem a melhoria de sua escolarização e a qualificação profissional; (Incluído pela Lei nº 13.840, de 2019)\n\nV - promover o acesso do usuário ou dependente de drogas a todos os serviços públicos; (Incluído pela Lei nº 13.840, de 2019)\n\nVI - estabelecer diretrizes para garantir a efetividade dos programas, ações e projetos das políticas sobre drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nVII - fomentar a criação de serviço de atendimento telefônico com orientações e informações para apoio aos usuários ou dependentes de drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nVIII - articular programas, ações e projetos de incentivo ao emprego, renda e capacitação para o trabalho, com objetivo de promover a inserção profissional da pessoa que haja cumprido o plano individual de atendimento nas fases de tratamento ou acolhimento; (Incluído pela Lei nº 13.840, de 2019)\n\nIX - promover formas coletivas de organização para o trabalho, redes de economia solidária e o cooperativismo, como forma de promover autonomia ao usuário ou dependente de drogas egresso de tratamento ou acolhimento, observando-se as especificidades regionais; (Incluído pela Lei nº 13.840, de 2019)\n\nX - propor a formulação de políticas públicas que conduzam à efetivação das diretrizes e princípios previstos no art. 22; (Incluído pela Lei nº 13.840, de 2019)\n\nXI - articular as instâncias de saúde, assistência social e de justiça no enfrentamento ao abuso de drogas; e (Incluído pela Lei nº 13.840, de 2019)\n\nXII - promover estudos e avaliação dos resultados das políticas sobre drogas. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 1º O plano de que trata o caput terá duração de 5 (cinco) anos a contar de sua aprovação.\n\n§ 2º O poder público deverá dar a mais ampla divulgação ao conteúdo do Plano Nacional de Políticas sobre Drogas."},{"chave":"art-8-e","sequencia":14,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO II-A","SEÇÃO II — DOS CONSELHOS DE POLÍTICAS SOBRE DROGAS"],"titulo":"SEÇÃO II — DOS CONSELHOS DE POLÍTICAS SOBRE DROGAS","rotulo":"Art. 8º-E","conteudo":"Os conselhos de políticas sobre drogas, constituídos por Estados, Distrito Federal e Municípios, terão os seguintes objetivos: (Incluído pela Lei nº 13.840, de 2019)\n\nI - auxiliar na elaboração de políticas sobre drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nII - colaborar com os órgãos governamentais no planejamento e na execução das políticas sobre drogas, visando à efetividade das políticas sobre drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nIII - propor a celebração de instrumentos de cooperação, visando à elaboração de programas, ações, atividades e projetos voltados à prevenção, tratamento, acolhimento, reinserção social e econômica e repressão ao tráfico ilícito de drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nIV - promover a realização de estudos, com o objetivo de subsidiar o planejamento das políticas sobre drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nV - propor políticas públicas que permitam a integração e a participação do usuário ou dependente de drogas no processo social, econômico, político e cultural no respectivo ente federado; e (Incluído pela Lei nº 13.840, de 2019)\n\nVI - desenvolver outras atividades relacionadas às políticas sobre drogas em consonância com o Sisnad e com os respectivos planos. (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-8-f","sequencia":15,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO II-A","SEÇÃO III — DOS MEMBROS DOS CONSELHOS DE POLÍTICAS SOBRE DROGAS"],"titulo":"SEÇÃO III — DOS MEMBROS DOS CONSELHOS DE POLÍTICAS SOBRE DROGAS","rotulo":"Art. 8º-F","conteudo":"(VETADO). (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-9","sequencia":16,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO III"],"titulo":"CAPÍTULO III","rotulo":"Art. 9º","conteudo":"(VETADO)"},{"chave":"art-10","sequencia":17,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO III"],"titulo":"CAPÍTULO III","rotulo":"Art. 10.","conteudo":"(VETADO)"},{"chave":"art-11","sequencia":18,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO III"],"titulo":"CAPÍTULO III","rotulo":"Art. 11.","conteudo":"(VETADO)"},{"chave":"art-12","sequencia":19,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO III"],"titulo":"CAPÍTULO III","rotulo":"Art. 12.","conteudo":"(VETADO)"},{"chave":"art-13","sequencia":20,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO III"],"titulo":"CAPÍTULO III","rotulo":"Art. 13.","conteudo":"(VETADO)"},{"chave":"art-14","sequencia":21,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO III"],"titulo":"CAPÍTULO III","rotulo":"Art. 14.","conteudo":"(VETADO)"},{"chave":"art-15","sequencia":22,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO IV — DO ACOMPANHAMENTO E DA AVALIAÇÃO DAS POLÍTICAS SOBRE DROGAS"],"titulo":"CAPÍTULO IV — DO ACOMPANHAMENTO E DA AVALIAÇÃO DAS POLÍTICAS SOBRE DROGAS","rotulo":"Art. 15.","conteudo":"(VETADO)"},{"chave":"art-16","sequencia":23,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO IV — DO ACOMPANHAMENTO E DA AVALIAÇÃO DAS POLÍTICAS SOBRE DROGAS"],"titulo":"CAPÍTULO IV — DO ACOMPANHAMENTO E DA AVALIAÇÃO DAS POLÍTICAS SOBRE DROGAS","rotulo":"Art. 16.","conteudo":"As instituições com atuação nas áreas da atenção à saúde e da assistência social que atendam usuários ou dependentes de drogas devem comunicar ao órgão competente do respectivo sistema municipal de saúde os casos atendidos e os óbitos ocorridos, preservando a identidade das pessoas, conforme orientações emanadas da União."},{"chave":"art-17","sequencia":24,"caminho":["LEI DE DROGAS","TÍTULO II — DO SISTEMA NACIONAL DE POLÍTICAS PÚBLICAS SOBRE DROGAS","CAPÍTULO IV — DO ACOMPANHAMENTO E DA AVALIAÇÃO DAS POLÍTICAS SOBRE DROGAS"],"titulo":"CAPÍTULO IV — DO ACOMPANHAMENTO E DA AVALIAÇÃO DAS POLÍTICAS SOBRE DROGAS","rotulo":"Art. 17.","conteudo":"Os dados estatísticos nacionais de repressão ao tráfico ilícito de drogas integrarão sistema de informações do Poder Executivo."},{"chave":"art-18","sequencia":25,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO I — DA PREVENÇÃO","SEÇÃO I — DAS DIRETRIZES"],"titulo":"SEÇÃO I — DAS DIRETRIZES","rotulo":"Art. 18.","conteudo":"Constituem atividades de prevenção do uso indevido de drogas, para efeito desta Lei, aquelas direcionadas para a redução dos fatores de vulnerabilidade e risco e para a promoção e o fortalecimento dos fatores de proteção."},{"chave":"art-19","sequencia":26,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO I — DA PREVENÇÃO","SEÇÃO I — DAS DIRETRIZES"],"titulo":"SEÇÃO I — DAS DIRETRIZES","rotulo":"Art. 19.","conteudo":"As atividades de prevenção do uso indevido de drogas devem observar os seguintes princípios e diretrizes:\n\nI - o reconhecimento do uso indevido de drogas como fator de interferência na qualidade de vida do indivíduo e na sua relação com a comunidade à qual pertence;\n\nII - a adoção de conceitos objetivos e de fundamentação científica como forma de orientar as ações dos serviços públicos comunitários e privados e de evitar preconceitos e estigmatização das pessoas e dos serviços que as atendam;\n\nIII - o fortalecimento da autonomia e da responsabilidade individual em relação ao uso indevido de drogas;\n\nIV - o compartilhamento de responsabilidades e a colaboração mútua com as instituições do setor privado e com os diversos segmentos sociais, incluindo usuários e dependentes de drogas e respectivos familiares, por meio do estabelecimento de parcerias;\n\nV - a adoção de estratégias preventivas diferenciadas e adequadas às especificidades socioculturais das diversas populações, bem como das diferentes drogas utilizadas;\n\nVI - o reconhecimento do “não-uso”, do “retardamento do uso” e da redução de riscos como resultados desejáveis das atividades de natureza preventiva, quando da definição dos objetivos a serem alcançados;\n\nVII - o tratamento especial dirigido às parcelas mais vulneráveis da população, levando em consideração as suas necessidades específicas;\n\nVIII - a articulação entre os serviços e organizações que atuam em atividades de prevenção do uso indevido de drogas e a rede de atenção a usuários e dependentes de drogas e respectivos familiares;\n\nIX - o investimento em alternativas esportivas, culturais, artísticas, profissionais, entre outras, como forma de inclusão social e de melhoria da qualidade de vida;\n\nX - o estabelecimento de políticas de formação continuada na área da prevenção do uso indevido de drogas para profissionais de educação nos 3 (três) níveis de ensino;\n\nXI - a implantação de projetos pedagógicos de prevenção do uso indevido de drogas, nas instituições de ensino público e privado, alinhados às Diretrizes Curriculares Nacionais e aos conhecimentos relacionados a drogas;\n\nXII - a observância das orientações e normas emanadas do Conad;\n\nXIII - o alinhamento às diretrizes dos órgãos de controle social de políticas setoriais específicas.\n\nParágrafo único. As atividades de prevenção do uso indevido de drogas dirigidas à criança e ao adolescente deverão estar em consonância com as diretrizes emanadas pelo Conselho Nacional dos Direitos da Criança e do Adolescente - Conanda."},{"chave":"art-19-a","sequencia":27,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO I — DA PREVENÇÃO","SEÇÃO II — DA SEMANA NACIONAL DE POLÍTICAS SOBRE DROGAS"],"titulo":"SEÇÃO II — DA SEMANA NACIONAL DE POLÍTICAS SOBRE DROGAS","rotulo":"Art. 19-A","conteudo":"Fica instituída a Semana Nacional de Políticas sobre Drogas, comemorada anualmente, na quarta semana de junho. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 1º No período de que trata o caput, serão intensificadas as ações de: (Incluído pela Lei nº 13.840, de 2019)\n\nI - difusão de informações sobre os problemas decorrentes do uso de drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nII - promoção de eventos para o debate público sobre as políticas sobre drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nIII - difusão de boas práticas de prevenção, tratamento, acolhimento e reinserção social e econômica de usuários de drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nIV - divulgação de iniciativas, ações e campanhas de prevenção do uso indevido de drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nV - mobilização da comunidade para a participação nas ações de prevenção e enfrentamento às drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nVI - mobilização dos sistemas de ensino previstos na Lei nº 9.394, de 20 de dezembro de 1996 - Lei de Diretrizes e Bases da Educação Nacional, na realização de atividades de prevenção ao uso de drogas. (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-20","sequencia":28,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO II — DAS ATIVIDADES DE PREVENÇÃO, TRATAMENTO, ACOLHIMENTO E DE REINSERÇÃO SOCIAL E ECONÔMICA DE USUÁRIOS OU DEPENDENTES DE DROGAS","SEÇÃO I — DISPOSIÇÕES GERAIS"],"titulo":"SEÇÃO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 20.","conteudo":"Constituem atividades de atenção ao usuário e dependente de drogas e respectivos familiares, para efeito desta Lei, aquelas que visem à melhoria da qualidade de vida e à redução dos riscos e dos danos associados ao uso de drogas."},{"chave":"art-21","sequencia":29,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO II — DAS ATIVIDADES DE PREVENÇÃO, TRATAMENTO, ACOLHIMENTO E DE REINSERÇÃO SOCIAL E ECONÔMICA DE USUÁRIOS OU DEPENDENTES DE DROGAS","SEÇÃO I — DISPOSIÇÕES GERAIS"],"titulo":"SEÇÃO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 21.","conteudo":"Constituem atividades de reinserção social do usuário ou do dependente de drogas e respectivos familiares, para efeito desta Lei, aquelas direcionadas para sua integração ou reintegração em redes sociais."},{"chave":"art-22","sequencia":30,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO II — DAS ATIVIDADES DE PREVENÇÃO, TRATAMENTO, ACOLHIMENTO E DE REINSERÇÃO SOCIAL E ECONÔMICA DE USUÁRIOS OU DEPENDENTES DE DROGAS","SEÇÃO I — DISPOSIÇÕES GERAIS"],"titulo":"SEÇÃO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 22.","conteudo":"As atividades de atenção e as de reinserção social do usuário e do dependente de drogas e respectivos familiares devem observar os seguintes princípios e diretrizes:\n\nI - respeito ao usuário e ao dependente de drogas, independentemente de quaisquer condições, observados os direitos fundamentais da pessoa humana, os princípios e diretrizes do Sistema Único de Saúde e da Política Nacional de Assistência Social;\n\nII - a adoção de estratégias diferenciadas de atenção e reinserção social do usuário e do dependente de drogas e respectivos familiares que considerem as suas peculiaridades socioculturais;\n\nIII - definição de projeto terapêutico individualizado, orientado para a inclusão social e para a redução de riscos e de danos sociais e à saúde;\n\nIV - atenção ao usuário ou dependente de drogas e aos respectivos familiares, sempre que possível, de forma multidisciplinar e por equipes multiprofissionais;\n\nV - observância das orientações e normas emanadas do Conad;\n\nVI - o alinhamento às diretrizes dos órgãos de controle social de políticas setoriais específicas.\n\nVII - estímulo à capacitação técnica e profissional; (Incluído pela Lei nº 13.840, de 2019)\n\nVIII - efetivação de políticas de reinserção social voltadas à educação continuada e ao trabalho; (Incluído pela Lei nº 13.840, de 2019)\n\nIX - observância do plano individual de atendimento na forma do art. 23-B desta Lei; (Incluído pela Lei nº 13.840, de 2019)\n\nX - orientação adequada ao usuário ou dependente de drogas quanto às consequências lesivas do uso de drogas, ainda que ocasional. (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-22-a","sequencia":31,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO II — DAS ATIVIDADES DE PREVENÇÃO, TRATAMENTO, ACOLHIMENTO E DE REINSERÇÃO SOCIAL E ECONÔMICA DE USUÁRIOS OU DEPENDENTES DE DROGAS","SEÇÃO II — DA EDUCAÇÃO NA REINSERÇÃO SOCIAL E ECONÔMICA"],"titulo":"SEÇÃO II — DA EDUCAÇÃO NA REINSERÇÃO SOCIAL E ECONÔMICA","rotulo":"Art. 22-A","conteudo":"As pessoas atendidas por órgãos integrantes do Sisnad terão atendimento nos programas de educação profissional e tecnológica, educação de jovens e adultos e alfabetização. (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-22-b","sequencia":32,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO II — DAS ATIVIDADES DE PREVENÇÃO, TRATAMENTO, ACOLHIMENTO E DE REINSERÇÃO SOCIAL E ECONÔMICA DE USUÁRIOS OU DEPENDENTES DE DROGAS","SEÇÃO III — DO TRABALHO NA REINSERÇÃO SOCIAL E ECONÔMICA"],"titulo":"SEÇÃO III — DO TRABALHO NA REINSERÇÃO SOCIAL E ECONÔMICA","rotulo":"Art. 22-B","conteudo":"(VETADO)."},{"chave":"art-23","sequencia":33,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO II — DAS ATIVIDADES DE PREVENÇÃO, TRATAMENTO, ACOLHIMENTO E DE REINSERÇÃO SOCIAL E ECONÔMICA DE USUÁRIOS OU DEPENDENTES DE DROGAS","SEÇÃO IV — DO TRATAMENTO DO USUÁRIO OU DEPENDENTE DE DROGAS"],"titulo":"SEÇÃO IV — DO TRATAMENTO DO USUÁRIO OU DEPENDENTE DE DROGAS","rotulo":"Art. 23.","conteudo":"As redes dos serviços de saúde da União, dos Estados, do Distrito Federal, dos Municípios desenvolverão programas de atenção ao usuário e ao dependente de drogas, respeitadas as diretrizes do Ministério da Saúde e os princípios explicitados no art. 22 desta Lei, obrigatória a previsão orçamentária adequada.\n\nParágrafo único. Será criada estratégia específica de assistência multiprofissional e interdisciplinar às mulheres usuárias e dependentes de álcool, em especial às gestantes e às puérperas, em consonância com os princípios da universalidade e da integralidade e com o disposto nos incisos I, II, III, IV, IX e X do caput do art. 22 desta Lei. (Incluído pela Lei nº 15.581, de 2025)"},{"chave":"art-23-a","sequencia":34,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO II — DAS ATIVIDADES DE PREVENÇÃO, TRATAMENTO, ACOLHIMENTO E DE REINSERÇÃO SOCIAL E ECONÔMICA DE USUÁRIOS OU DEPENDENTES DE DROGAS","SEÇÃO IV — DO TRATAMENTO DO USUÁRIO OU DEPENDENTE DE DROGAS"],"titulo":"SEÇÃO IV — DO TRATAMENTO DO USUÁRIO OU DEPENDENTE DE DROGAS","rotulo":"Art. 23-A","conteudo":"O tratamento do usuário ou dependente de drogas deverá ser ordenado em uma rede de atenção à saúde, com prioridade para as modalidades de tratamento ambulatorial, incluindo excepcionalmente formas de internação em unidades de saúde e hospitais gerais nos termos de normas dispostas pela União e articuladas com os serviços de assistência social e em etapas que permitam: (Incluído pela Lei nº 13.840, de 2019)\n\nI - articular a atenção com ações preventivas que atinjam toda a população; (Incluído pela Lei nº 13.840, de 2019)\n\nII - orientar-se por protocolos técnicos predefinidos, baseados em evidências científicas, oferecendo atendimento individualizado ao usuário ou dependente de drogas com abordagem preventiva e, sempre que indicado, ambulatorial; (Incluído pela Lei nº 13.840, de 2019)\n\nIII - preparar para a reinserção social e econômica, respeitando as habilidades e projetos individuais por meio de programas que articulem educação, capacitação para o trabalho, esporte, cultura e acompanhamento individualizado; e (Incluído pela Lei nº 13.840, de 2019)\n\nIV - acompanhar os resultados pelo SUS, Suas e Sisnad, de forma articulada. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 1º Caberá à União dispor sobre os protocolos técnicos de tratamento, em âmbito nacional. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 2º A internação de dependentes de drogas somente será realizada em unidades de saúde ou hospitais gerais, dotados de equipes multidisciplinares e deverá ser obrigatoriamente autorizada por médico devidamente registrado no Conselho Regional de Medicina - CRM do Estado onde se localize o estabelecimento no qual se dará a internação. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 3º São considerados 2 (dois) tipos de internação: (Incluído pela Lei nº 13.840, de 2019)\n\nI - internação voluntária: aquela que se dá com o consentimento do dependente de drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nII - internação involuntária: aquela que se dá, sem o consentimento do dependente, a pedido de familiar ou do responsável legal ou, na absoluta falta deste, de servidor público da área de saúde, da assistência social ou dos órgãos públicos integrantes do Sisnad, com exceção de servidores da área de segurança pública, que constate a existência de motivos que justifiquem a medida. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 4º A internação voluntária: (Incluído pela Lei nº 13.840, de 2019)\n\nI - deverá ser precedida de declaração escrita da pessoa solicitante de que optou por este regime de tratamento; (Incluído pela Lei nº 13.840, de 2019)\n\nII - seu término dar-se-á por determinação do médico responsável ou por solicitação escrita da pessoa que deseja interromper o tratamento. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 5º A internação involuntária: (Incluído pela Lei nº 13.840, de 2019)\n\nI - deve ser realizada após a formalização da decisão por médico responsável; (Incluído pela Lei nº 13.840, de 2019)\n\nII - será indicada depois da avaliação sobre o tipo de droga utilizada, o padrão de uso e na hipótese comprovada da impossibilidade de utilização de outras alternativas terapêuticas previstas na rede de atenção à saúde; (Incluído pela Lei nº 13.840, de 2019)\n\nIII - perdurará apenas pelo tempo necessário à desintoxicação, no prazo máximo de 90 (noventa) dias, tendo seu término determinado pelo médico responsável; (Incluído pela Lei nº 13.840, de 2019)\n\nIV - a família ou o representante legal poderá, a qualquer tempo, requerer ao médico a interrupção do tratamento. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 6º A internação, em qualquer de suas modalidades, só será indicada quando os recursos extra-hospitalares se mostrarem insuficientes. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 7º Todas as internações e altas de que trata esta Lei deverão ser informadas, em, no máximo, de 72 (setenta e duas) horas, ao Ministério Público, à Defensoria Pública e a outros órgãos de fiscalização, por meio de sistema informatizado único, na forma do regulamento desta Lei. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 8º É garantido o sigilo das informações disponíveis no sistema referido no § 7º e o acesso será permitido apenas às pessoas autorizadas a conhecê-las, sob pena de responsabilidade. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 9º É vedada a realização de qualquer modalidade de internação nas comunidades terapêuticas acolhedoras. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 10. O planejamento e a execução do projeto terapêutico individual deverão observar, no que couber, o previsto na Lei nº 10.216, de 6 de abril de 2001, que dispõe sobre a proteção e os direitos das pessoas portadoras de transtornos mentais e redireciona o modelo assistencial em saúde mental. (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-23-b","sequencia":35,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO II — DAS ATIVIDADES DE PREVENÇÃO, TRATAMENTO, ACOLHIMENTO E DE REINSERÇÃO SOCIAL E ECONÔMICA DE USUÁRIOS OU DEPENDENTES DE DROGAS","SEÇÃO V — DO PLANO INDIVIDUAL DE ATENDIMENTO"],"titulo":"SEÇÃO V — DO PLANO INDIVIDUAL DE ATENDIMENTO","rotulo":"Art. 23-B","conteudo":"O atendimento ao usuário ou dependente de drogas na rede de atenção à saúde dependerá de: (Incluído pela Lei nº 13.840, de 2019)\n\nI - avaliação prévia por equipe técnica multidisciplinar e multissetorial; e (Incluído pela Lei nº 13.840, de 2019)\n\nII - elaboração de um Plano Individual de Atendimento - PIA. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 1º A avaliação prévia da equipe técnica subsidiará a elaboração e execução do projeto terapêutico individual a ser adotado, levantando no mínimo: (Incluído pela Lei nº 13.840, de 2019)\n\nI - o tipo de droga e o padrão de seu uso; e (Incluído pela Lei nº 13.840, de 2019)\n\nII - o risco à saúde física e mental do usuário ou dependente de drogas ou das pessoas com as quais convive. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 2º (VETADO). (Incluído pela Lei nº 13.840, de 2019)\n\n§ 3º O PIA deverá contemplar a participação dos familiares ou responsáveis, os quais têm o dever de contribuir com o processo, sendo esses, no caso de crianças e adolescentes, passíveis de responsabilização civil, administrativa e criminal, nos termos da Lei nº 8.069, de 13 de julho de 1990 - Estatuto da Criança e do Adolescente. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 4º O PIA será inicialmente elaborado sob a responsabilidade da equipe técnica do primeiro projeto terapêutico que atender o usuário ou dependente de drogas e será atualizado ao longo das diversas fases do atendimento. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 5º Constarão do plano individual, no mínimo: (Incluído pela Lei nº 13.840, de 2019)\n\nI - os resultados da avaliação multidisciplinar; (Incluído pela Lei nº 13.840, de 2019)\n\nII - os objetivos declarados pelo atendido; (Incluído pela Lei nº 13.840, de 2019)\n\nIII - a previsão de suas atividades de integração social ou capacitação profissional; (Incluído pela Lei nº 13.840, de 2019)\n\nIV - atividades de integração e apoio à família; (Incluído pela Lei nº 13.840, de 2019)\n\nV - formas de participação da família para efetivo cumprimento do plano individual; (Incluído pela Lei nº 13.840, de 2019)\n\nVI - designação do projeto terapêutico mais adequado para o cumprimento do previsto no plano; e (Incluído pela Lei nº 13.840, de 2019)\n\nVII - as medidas específicas de atenção à saúde do atendido. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 6º O PIA será elaborado no prazo de até 30 (trinta) dias da data do ingresso no atendimento. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 7º As informações produzidas na avaliação e as registradas no plano individual de atendimento são consideradas sigilosas. (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-24","sequencia":36,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO II — DAS ATIVIDADES DE PREVENÇÃO, TRATAMENTO, ACOLHIMENTO E DE REINSERÇÃO SOCIAL E ECONÔMICA DE USUÁRIOS OU DEPENDENTES DE DROGAS","SEÇÃO V — DO PLANO INDIVIDUAL DE ATENDIMENTO"],"titulo":"SEÇÃO V — DO PLANO INDIVIDUAL DE ATENDIMENTO","rotulo":"Art. 24.","conteudo":"A União, os Estados, o Distrito Federal e os Municípios poderão conceder benefícios às instituições privadas que desenvolverem programas de reinserção no mercado de trabalho, do usuário e do dependente de drogas encaminhados por órgão oficial."},{"chave":"art-25","sequencia":37,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO II — DAS ATIVIDADES DE PREVENÇÃO, TRATAMENTO, ACOLHIMENTO E DE REINSERÇÃO SOCIAL E ECONÔMICA DE USUÁRIOS OU DEPENDENTES DE DROGAS","SEÇÃO V — DO PLANO INDIVIDUAL DE ATENDIMENTO"],"titulo":"SEÇÃO V — DO PLANO INDIVIDUAL DE ATENDIMENTO","rotulo":"Art. 25.","conteudo":"As instituições da sociedade civil, sem fins lucrativos, com atuação nas áreas da atenção à saúde e da assistência social, que atendam usuários ou dependentes de drogas poderão receber recursos do Funad, condicionados à sua disponibilidade orçamentária e financeira."},{"chave":"art-26","sequencia":38,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO II — DAS ATIVIDADES DE PREVENÇÃO, TRATAMENTO, ACOLHIMENTO E DE REINSERÇÃO SOCIAL E ECONÔMICA DE USUÁRIOS OU DEPENDENTES DE DROGAS","SEÇÃO V — DO PLANO INDIVIDUAL DE ATENDIMENTO"],"titulo":"SEÇÃO V — DO PLANO INDIVIDUAL DE ATENDIMENTO","rotulo":"Art. 26.","conteudo":"O usuário e o dependente de drogas que, em razão da prática de infração penal, estiverem cumprindo pena privativa de liberdade ou submetidos a medida de segurança, têm garantidos os serviços de atenção à sua saúde, definidos pelo respectivo sistema penitenciário."},{"chave":"art-26-a","sequencia":39,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO II — DAS ATIVIDADES DE PREVENÇÃO, TRATAMENTO, ACOLHIMENTO E DE REINSERÇÃO SOCIAL E ECONÔMICA DE USUÁRIOS OU DEPENDENTES DE DROGAS","SEÇÃO VI — DO ACOLHIMENTO EM COMUNIDADE TERAPÊUTICA ACOLHEDORA"],"titulo":"SEÇÃO VI — DO ACOLHIMENTO EM COMUNIDADE TERAPÊUTICA ACOLHEDORA","rotulo":"Art. 26-A","conteudo":"O acolhimento do usuário ou dependente de drogas na comunidade terapêutica acolhedora caracteriza-se por: (Incluído pela Lei nº 13.840, de 2019)\n\nI - oferta de projetos terapêuticos ao usuário ou dependente de drogas que visam à abstinência; (Incluído pela Lei nº 13.840, de 2019)\n\nII - adesão e permanência voluntária, formalizadas por escrito, entendida como uma etapa transitória para a reinserção social e econômica do usuário ou dependente de drogas; (Incluído pela Lei nº 13.840, de 2019)\n\nIII - ambiente residencial, propício à formação de vínculos, com a convivência entre os pares, atividades práticas de valor educativo e a promoção do desenvolvimento pessoal, vocacionada para acolhimento ao usuário ou dependente de drogas em vulnerabilidade social; (Incluído pela Lei nº 13.840, de 2019)\n\nIV - avaliação médica prévia; (Incluído pela Lei nº 13.840, de 2019)\n\nV - elaboração de plano individual de atendimento na forma do art. 23-B desta Lei; e (Incluído pela Lei nº 13.840, de 2019)\n\nVI - vedação de isolamento físico do usuário ou dependente de drogas. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 1º Não são elegíveis para o acolhimento as pessoas com comprometimentos biológicos e psicológicos de natureza grave que mereçam atenção médico-hospitalar contínua ou de emergência, caso em que deverão ser encaminhadas à rede de saúde. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 2º (VETADO). (Incluído pela Lei nº 13.840, de 2019)\n\n§ 3º (VETADO). (Incluído pela Lei nº 13.840, de 2019)\n\n§ 4º (VETADO). (Incluído pela Lei nº 13.840, de 2019)\n\n§ 5º (VETADO). (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-27","sequencia":40,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO III — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO III — DOS CRIMES E DAS PENAS","rotulo":"Art. 27.","conteudo":"As penas previstas neste Capítulo poderão ser aplicadas isolada ou cumulativamente, bem como substituídas a qualquer tempo, ouvidos o Ministério Público e o defensor. (Vide RE 635659)"},{"chave":"art-28","sequencia":41,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO III — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO III — DOS CRIMES E DAS PENAS","rotulo":"Art. 28.","conteudo":"Quem adquirir, guardar, tiver em depósito, transportar ou trouxer consigo, para consumo pessoal, drogas sem autorização ou em desacordo com determinação legal ou regulamentar será submetido às seguintes penas:\n\nI - advertência sobre os efeitos das drogas;\n\nII - prestação de serviços à comunidade;\n\nIII - medida educativa de comparecimento a programa ou curso educativo.\n\n§ 1º Às mesmas medidas submete-se quem, para seu consumo pessoal, semeia, cultiva ou colhe plantas destinadas à preparação de pequena quantidade de substância ou produto capaz de causar dependência física ou psíquica.\n\n§ 2º Para determinar se a droga destinava-se a consumo pessoal, o juiz atenderá à natureza e à quantidade da substância apreendida, ao local e às condições em que se desenvolveu a ação, às circunstâncias sociais e pessoais, bem como à conduta e aos antecedentes do agente.\n\n§ 3º As penas previstas nos incisos II e III do caput deste artigo serão aplicadas pelo prazo máximo de 5 (cinco) meses.\n\n§ 4º Em caso de reincidência, as penas previstas nos incisos II e III do caput deste artigo serão aplicadas pelo prazo máximo de 10 (dez) meses.\n\n§ 5º A prestação de serviços à comunidade será cumprida em programas comunitários, entidades educacionais ou assistenciais, hospitais, estabelecimentos congêneres, públicos ou privados sem fins lucrativos, que se ocupem, preferencialmente, da prevenção do consumo ou da recuperação de usuários e dependentes de drogas.\n\n§ 6º Para garantia do cumprimento das medidas educativas a que se refere o caput, nos incisos I, II e III, a que injustificadamente se recuse o agente, poderá o juiz submetê-lo, sucessivamente a:\n\nI - admoestação verbal;\n\nII - multa.\n\n§ 7º O juiz determinará ao Poder Público que coloque à disposição do infrator, gratuitamente, estabelecimento de saúde, preferencialmente ambulatorial, para tratamento especializado."},{"chave":"art-29","sequencia":42,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO III — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO III — DOS CRIMES E DAS PENAS","rotulo":"Art. 29.","conteudo":"Na imposição da medida educativa a que se refere o inciso II do § 6º do art. 28, o juiz, atendendo à reprovabilidade da conduta, fixará o número de dias-multa, em quantidade nunca inferior a 40 (quarenta) nem superior a 100 (cem), atribuindo depois a cada um, segundo a capacidade econômica do agente, o valor de um trinta avos até 3 (três) vezes o valor do maior salário mínimo.\n\nParágrafo único. Os valores decorrentes da imposição da multa a que se refere o § 6º do art. 28 serão creditados à conta do Fundo Nacional Antidrogas."},{"chave":"art-30","sequencia":43,"caminho":["LEI DE DROGAS","TÍTULO III — DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS","CAPÍTULO III — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO III — DOS CRIMES E DAS PENAS","rotulo":"Art. 30.","conteudo":"Prescrevem em 2 (dois) anos a imposição e a execução das penas, observado, no tocante à interrupção do prazo, o disposto nos arts. 107 e seguintes do Código Penal."},{"chave":"art-31","sequencia":44,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 31.","conteudo":"É indispensável a licença prévia da autoridade competente para produzir, extrair, fabricar, transformar, preparar, possuir, manter em depósito, importar, exportar, reexportar, remeter, transportar, expor, oferecer, vender, comprar, trocar, ceder ou adquirir, para qualquer fim, drogas ou matéria-prima destinada à sua preparação, observadas as demais exigências legais."},{"chave":"art-32","sequencia":45,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 32.","conteudo":"As plantações ilícitas serão imediatamente destruídas pelo delegado de polícia na forma do art. 50-A, que recolherá quantidade suficiente para exame pericial, de tudo lavrando auto de levantamento das condições encontradas, com a delimitação do local, asseguradas as medidas necessárias para a preservação da prova. (Redação dada pela Lei nº 12.961, de 2014)\n\n§ 1º (Revogado). (Redação dada pela Lei nº 12.961, de 2014)\n\n§ 2º (Revogado). (Redação dada pela Lei nº 12.961, de 2014)\n\n§ 3º Em caso de ser utilizada a queimada para destruir a plantação, observar-se-á, além das cautelas necessárias à proteção ao meio ambiente, o disposto no Decreto nº 2.661, de 8 de julho de 1998, no que couber, dispensada a autorização prévia do órgão próprio do Sistema Nacional do Meio Ambiente - Sisnama.\n\n§ 4º As glebas cultivadas com plantações ilícitas serão expropriadas, conforme o disposto no art. 243 da Constituição Federal, de acordo com a legislação em vigor."},{"chave":"art-33","sequencia":46,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO II — DOS CRIMES"],"titulo":"CAPÍTULO II — DOS CRIMES","rotulo":"Art. 33.","conteudo":"Importar, exportar, remeter, preparar, produzir, fabricar, adquirir, vender, expor à venda, oferecer, ter em depósito, transportar, trazer consigo, guardar, prescrever, ministrar, entregar a consumo ou fornecer drogas, ainda que gratuitamente, sem autorização ou em desacordo com determinação legal ou regulamentar:\n\nPena - reclusão de 5 (cinco) a 15 (quinze) anos e pagamento de 500 (quinhentos) a 1.500 (mil e quinhentos) dias-multa.\n\n§ 1º Nas mesmas penas incorre quem:\n\nI - importa, exporta, remete, produz, fabrica, adquire, vende, expõe à venda, oferece, fornece, tem em depósito, transporta, traz consigo ou guarda, ainda que gratuitamente, sem autorização ou em desacordo com determinação legal ou regulamentar, matéria-prima, insumo ou produto químico destinado à preparação de drogas;\n\nII - semeia, cultiva ou faz a colheita, sem autorização ou em desacordo com determinação legal ou regulamentar, de plantas que se constituam em matéria-prima para a preparação de drogas;\n\nIII - utiliza local ou bem de qualquer natureza de que tem a propriedade, posse, administração, guarda ou vigilância, ou consente que outrem dele se utilize, ainda que gratuitamente, sem autorização ou em desacordo com determinação legal ou regulamentar, para o tráfico ilícito de drogas.\n\nIV - vende ou entrega drogas ou matéria-prima, insumo ou produto químico destinado à preparação de drogas, sem autorização ou em desacordo com a determinação legal ou regulamentar, a agente policial disfarçado, quando presentes elementos probatórios razoáveis de conduta criminal preexistente. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 2º Induzir, instigar ou auxiliar alguém ao uso indevido de droga: (Vide ADI nº 4.274)\n\nPena - detenção, de 1 (um) a 3 (três) anos, e multa de 100 (cem) a 300 (trezentos) dias-multa.\n\n§ 3º Oferecer droga, eventualmente e sem objetivo de lucro, a pessoa de seu relacionamento, para juntos a consumirem:\n\nPena - detenção, de 6 (seis) meses a 1 (um) ano, e pagamento de 700 (setecentos) a 1.500 (mil e quinhentos) dias-multa, sem prejuízo das penas previstas no art. 28.\n\n§ 4º Nos delitos definidos no caput e no § 1º deste artigo, as penas poderão ser reduzidas de um sexto a dois terços, desde que o agente seja primário, de bons antecedentes, não se dedique às atividades criminosas nem integre organização criminosa. (Vide Resolução nº 5, de 2012)"},{"chave":"art-34","sequencia":47,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO II — DOS CRIMES"],"titulo":"CAPÍTULO II — DOS CRIMES","rotulo":"Art. 34.","conteudo":"Fabricar, adquirir, utilizar, transportar, oferecer, vender, distribuir, entregar a qualquer título, possuir, guardar ou fornecer, ainda que gratuitamente, maquinário, aparelho, instrumento ou qualquer objeto destinado à fabricação, preparação, produção ou transformação de drogas, sem autorização ou em desacordo com determinação legal ou regulamentar:\n\nPena - reclusão, de 3 (três) a 10 (dez) anos, e pagamento de 1.200 (mil e duzentos) a 2.000 (dois mil) dias-multa."},{"chave":"art-35","sequencia":48,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO II — DOS CRIMES"],"titulo":"CAPÍTULO II — DOS CRIMES","rotulo":"Art. 35.","conteudo":"Associarem-se duas ou mais pessoas para o fim de praticar, reiteradamente ou não, qualquer dos crimes previstos nos arts. 33, caput e § 1º, e 34 desta Lei:\n\nPena - reclusão, de 3 (três) a 10 (dez) anos, e pagamento de 700 (setecentos) a 1.200 (mil e duzentos) dias-multa.\n\nParágrafo único. Nas mesmas penas do caput deste artigo incorre quem se associa para a prática reiterada do crime definido no art. 36 desta Lei."},{"chave":"art-36","sequencia":49,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO II — DOS CRIMES"],"titulo":"CAPÍTULO II — DOS CRIMES","rotulo":"Art. 36.","conteudo":"Financiar ou custear a prática de qualquer dos crimes previstos nos arts. 33, caput e § 1º, e 34 desta Lei:\n\nPena - reclusão, de 8 (oito) a 20 (vinte) anos, e pagamento de 1.500 (mil e quinhentos) a 4.000 (quatro mil) dias-multa."},{"chave":"art-37","sequencia":50,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO II — DOS CRIMES"],"titulo":"CAPÍTULO II — DOS CRIMES","rotulo":"Art. 37.","conteudo":"Colaborar, como informante, com grupo, organização ou associação destinados à prática de qualquer dos crimes previstos nos arts. 33, caput e § 1º, e 34 desta Lei:\n\nPena - reclusão, de 2 (dois) a 6 (seis) anos, e pagamento de 300 (trezentos) a 700 (setecentos) dias-multa."},{"chave":"art-38","sequencia":51,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO II — DOS CRIMES"],"titulo":"CAPÍTULO II — DOS CRIMES","rotulo":"Art. 38.","conteudo":"Prescrever ou ministrar, culposamente, drogas, sem que delas necessite o paciente, ou fazê-lo em doses excessivas ou em desacordo com determinação legal ou regulamentar:\n\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e pagamento de 50 (cinqüenta) a 200 (duzentos) dias-multa.\n\nParágrafo único. O juiz comunicará a condenação ao Conselho Federal da categoria profissional a que pertença o agente."},{"chave":"art-39","sequencia":52,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO II — DOS CRIMES"],"titulo":"CAPÍTULO II — DOS CRIMES","rotulo":"Art. 39.","conteudo":"Conduzir embarcação ou aeronave após o consumo de drogas, expondo a dano potencial a incolumidade de outrem:\n\nPena - detenção, de 6 (seis) meses a 3 (três) anos, além da apreensão do veículo, cassação da habilitação respectiva ou proibição de obtê-la, pelo mesmo prazo da pena privativa de liberdade aplicada, e pagamento de 200 (duzentos) a 400 (quatrocentos) dias-multa.\n\nParágrafo único. As penas de prisão e multa, aplicadas cumulativamente com as demais, serão de 4 (quatro) a 6 (seis) anos e de 400 (quatrocentos) a 600 (seiscentos) dias-multa, se o veículo referido no caput deste artigo for de transporte coletivo de passageiros."},{"chave":"art-40","sequencia":53,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO II — DOS CRIMES"],"titulo":"CAPÍTULO II — DOS CRIMES","rotulo":"Art. 40.","conteudo":"As penas previstas nos arts. 33 a 37 desta Lei são aumentadas de um sexto a dois terços, se:\n\nI - a natureza, a procedência da substância ou do produto apreendido e as circunstâncias do fato evidenciarem a transnacionalidade do delito;\n\nII - o agente praticar o crime prevalecendo-se de função pública ou no desempenho de missão de educação, poder familiar, guarda ou vigilância;\n\nIII - a infração tiver sido cometida nas dependências ou imediações de estabelecimentos prisionais, de ensino ou hospitalares, de sedes de entidades estudantis, sociais, culturais, recreativas, esportivas, ou beneficentes, de locais de trabalho coletivo, de recintos onde se realizem espetáculos ou diversões de qualquer natureza, de serviços de tratamento de dependentes de drogas ou de reinserção social, de unidades militares ou policiais ou em transportes públicos;\n\nIV - o crime tiver sido praticado com violência, grave ameaça, emprego de arma de fogo, ou qualquer processo de intimidação difusa ou coletiva;\n\nV - caracterizado o tráfico entre Estados da Federação ou entre estes e o Distrito Federal;\n\nVI - sua prática envolver ou visar a atingir criança ou adolescente ou a quem tenha, por qualquer motivo, diminuída ou suprimida a capacidade de entendimento e determinação;\n\nVII - o agente financiar ou custear a prática do crime."},{"chave":"art-40-a","sequencia":54,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO II — DOS CRIMES"],"titulo":"CAPÍTULO II — DOS CRIMES","rotulo":"Art. 40-A","conteudo":"As penas previstas nos arts. 33 a 37 desta Lei serão aplicadas em dobro se o crime tiver sido praticado por integrante de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada, no contexto da atuação ou para a consecução das condutas previstas no art. 2º da lei que institui o marco legal do combate ao crime organizado no Brasil. (Incluído pela Lei nº 15.358, de 2026)\n\nParágrafo único. Aplica-se a pena do concurso material prevista no art. 69 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), se o crime tiver sido praticado com o emprego de arma de fogo, independentemente de o seu uso estar diretamente ligado ao comércio ilícito de entorpecentes ou de o artefato ter sido utilizado para assegurar o sucesso da mercancia. (Incluído pela Lei nº 15.358, de 2026)"},{"chave":"art-41","sequencia":55,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO II — DOS CRIMES"],"titulo":"CAPÍTULO II — DOS CRIMES","rotulo":"Art. 41.","conteudo":"O indiciado ou acusado que colaborar voluntariamente com a investigação policial e o processo criminal na identificação dos demais co-autores ou partícipes do crime e na recuperação total ou parcial do produto do crime, no caso de condenação, terá pena reduzida de um terço a dois terços."},{"chave":"art-42","sequencia":56,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO II — DOS CRIMES"],"titulo":"CAPÍTULO II — DOS CRIMES","rotulo":"Art. 42.","conteudo":"O juiz, na fixação das penas, considerará, com preponderância sobre o previsto no art. 59 do Código Penal, a natureza e a quantidade da substância ou do produto, a personalidade e a conduta social do agente."},{"chave":"art-43","sequencia":57,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO II — DOS CRIMES"],"titulo":"CAPÍTULO II — DOS CRIMES","rotulo":"Art. 43.","conteudo":"Na fixação da multa a que se referem os arts. 33 a 39 desta Lei, o juiz, atendendo ao que dispõe o art. 42 desta Lei, determinará o número de dias-multa, atribuindo a cada um, segundo as condições econômicas dos acusados, valor não inferior a um trinta avos nem superior a 5 (cinco) vezes o maior salário-mínimo.\n\nParágrafo único. As multas, que em caso de concurso de crimes serão impostas sempre cumulativamente, podem ser aumentadas até o décuplo se, em virtude da situação econômica do acusado, considerá-las o juiz ineficazes, ainda que aplicadas no máximo."},{"chave":"art-44","sequencia":58,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO II — DOS CRIMES"],"titulo":"CAPÍTULO II — DOS CRIMES","rotulo":"Art. 44.","conteudo":"Os crimes previstos nos arts. 33, caput e § 1º, e 34 a 37 desta Lei são inafiançáveis e insuscetíveis de sursis, graça, indulto, anistia e liberdade provisória, vedada a conversão de suas penas em restritivas de direitos.\n\nParágrafo único. Nos crimes previstos no caput deste artigo, dar-se-á o livramento condicional após o cumprimento de dois terços da pena, vedada sua concessão ao reincidente específico."},{"chave":"art-45","sequencia":59,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO II — DOS CRIMES"],"titulo":"CAPÍTULO II — DOS CRIMES","rotulo":"Art. 45.","conteudo":"É isento de pena o agente que, em razão da dependência, ou sob o efeito, proveniente de caso fortuito ou força maior, de droga, era, ao tempo da ação ou da omissão, qualquer que tenha sido a infração penal praticada, inteiramente incapaz de entender o caráter ilícito do fato ou de determinar-se de acordo com esse entendimento.\n\nParágrafo único. Quando absolver o agente, reconhecendo, por força pericial, que este apresentava, à época do fato previsto neste artigo, as condições referidas no caput deste artigo, poderá determinar o juiz, na sentença, o seu encaminhamento para tratamento médico adequado."},{"chave":"art-46","sequencia":60,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO II — DOS CRIMES"],"titulo":"CAPÍTULO II — DOS CRIMES","rotulo":"Art. 46.","conteudo":"As penas podem ser reduzidas de um terço a dois terços se, por força das circunstâncias previstas no art. 45 desta Lei, o agente não possuía, ao tempo da ação ou da omissão, a plena capacidade de entender o caráter ilícito do fato ou de determinar-se de acordo com esse entendimento."},{"chave":"art-47","sequencia":61,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO II — DOS CRIMES"],"titulo":"CAPÍTULO II — DOS CRIMES","rotulo":"Art. 47.","conteudo":"Na sentença condenatória, o juiz, com base em avaliação que ateste a necessidade de encaminhamento do agente para tratamento, realizada por profissional de saúde com competência específica na forma da lei, determinará que a tal se proceda, observado o disposto no art. 26 desta Lei."},{"chave":"art-48","sequencia":62,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO III — DO PROCEDIMENTO PENAL"],"titulo":"CAPÍTULO III — DO PROCEDIMENTO PENAL","rotulo":"Art. 48.","conteudo":"O procedimento relativo aos processos por crimes definidos neste Título rege-se pelo disposto neste Capítulo, aplicando-se, subsidiariamente, as disposições do Código de Processo Penal e da Lei de Execução Penal.\n\n§ 1º O agente de qualquer das condutas previstas no art. 28 desta Lei, salvo se houver concurso com os crimes previstos nos arts. 33 a 37 desta Lei, será processado e julgado na forma dos arts. 60 e seguintes da Lei nº 9.099, de 26 de setembro de 1995, que dispõe sobre os Juizados Especiais Criminais.\n\n§ 2º Tratando-se da conduta prevista no art. 28 desta Lei, não se imporá prisão em flagrante, devendo o autor do fato ser imediatamente encaminhado ao juízo competente ou, na falta deste, assumir o compromisso de a ele comparecer, lavrando-se termo circunstanciado e providenciando-se as requisições dos exames e perícias necessários.\n\n§ 3º Se ausente a autoridade judicial, as providências previstas no § 2º deste artigo serão tomadas de imediato pela autoridade policial, no local em que se encontrar, vedada a detenção do agente. (Vide ADIN 3807)\n\n§ 4º Concluídos os procedimentos de que trata o § 2º deste artigo, o agente será submetido a exame de corpo de delito, se o requerer ou se a autoridade de polícia judiciária entender conveniente, e em seguida liberado.\n\n§ 5º Para os fins do disposto no art. 76 da Lei nº 9.099, de 1995, que dispõe sobre os Juizados Especiais Criminais, o Ministério Público poderá propor a aplicação imediata de pena prevista no art. 28 desta Lei, a ser especificada na proposta."},{"chave":"art-49","sequencia":63,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO III — DO PROCEDIMENTO PENAL"],"titulo":"CAPÍTULO III — DO PROCEDIMENTO PENAL","rotulo":"Art. 49.","conteudo":"Tratando-se de condutas tipificadas nos arts. 33, caput e § 1º, e 34 a 37 desta Lei, o juiz, sempre que as circunstâncias o recomendem, empregará os instrumentos protetivos de colaboradores e testemunhas previstos na Lei nº 9.807, de 13 de julho de 1999."},{"chave":"art-50","sequencia":64,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO III — DO PROCEDIMENTO PENAL","SEÇÃO I — DA INVESTIGAÇÃO"],"titulo":"SEÇÃO I — DA INVESTIGAÇÃO","rotulo":"Art. 50.","conteudo":"Ocorrendo prisão em flagrante, a autoridade de polícia judiciária fará, imediatamente, comunicação ao juiz competente, remetendo-lhe cópia do auto lavrado, do qual será dada vista ao órgão do Ministério Público, em 24 (vinte e quatro) horas.\n\n§ 1º Para efeito da lavratura do auto de prisão em flagrante e estabelecimento da materialidade do delito, é suficiente o laudo de constatação da natureza e quantidade da droga, firmado por perito oficial ou, na falta deste, por pessoa idônea.\n\n§ 2º O perito que subscrever o laudo a que se refere o § 1º deste artigo não ficará impedido de participar da elaboração do laudo definitivo.\n\n§ 3º Recebida cópia do auto de prisão em flagrante, o juiz, no prazo de 10 (dez) dias, certificará a regularidade formal do laudo de constatação e determinará a destruição das drogas apreendidas, guardando-se amostra necessária à realização do laudo definitivo. (Incluído pela Lei nº 12.961, de 2014)\n\n§ 4º A destruição das drogas será executada pelo delegado de polícia competente no prazo de 15 (quinze) dias na presença do Ministério Público e da autoridade sanitária. (Incluído pela Lei nº 12.961, de 2014)\n\n§ 5º O local será vistoriado antes e depois de efetivada a destruição das drogas referida no § 3º, sendo lavrado auto circunstanciado pelo delegado de polícia, certificando-se neste a destruição total delas. (Incluído pela Lei nº 12.961, de 2014)"},{"chave":"art-50-a","sequencia":65,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO III — DO PROCEDIMENTO PENAL","SEÇÃO I — DA INVESTIGAÇÃO"],"titulo":"SEÇÃO I — DA INVESTIGAÇÃO","rotulo":"Art. 50-A","conteudo":"A destruição das drogas apreendidas sem a ocorrência de prisão em flagrante será feita por incineração, no prazo máximo de 30 (trinta) dias contados da data da apreensão, guardando-se amostra necessária à realização do laudo definitivo. (Redação dada pela Lei nº 13.840, de 2019)"},{"chave":"art-51","sequencia":66,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO III — DO PROCEDIMENTO PENAL","SEÇÃO I — DA INVESTIGAÇÃO"],"titulo":"SEÇÃO I — DA INVESTIGAÇÃO","rotulo":"Art. 51.","conteudo":"O inquérito policial será concluído no prazo de 30 (trinta) dias, se o indiciado estiver preso, e de 90 (noventa) dias, quando solto.\n\nParágrafo único. Os prazos a que se refere este artigo podem ser duplicados pelo juiz, ouvido o Ministério Público, mediante pedido justificado da autoridade de polícia judiciária."},{"chave":"art-52","sequencia":67,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO III — DO PROCEDIMENTO PENAL","SEÇÃO I — DA INVESTIGAÇÃO"],"titulo":"SEÇÃO I — DA INVESTIGAÇÃO","rotulo":"Art. 52.","conteudo":"Findos os prazos a que se refere o art. 51 desta Lei, a autoridade de polícia judiciária, remetendo os autos do inquérito ao juízo:\n\nI - relatará sumariamente as circunstâncias do fato, justificando as razões que a levaram à classificação do delito, indicando a quantidade e natureza da substância ou do produto apreendido, o local e as condições em que se desenvolveu a ação criminosa, as circunstâncias da prisão, a conduta, a qualificação e os antecedentes do agente; ou\n\nII - requererá sua devolução para a realização de diligências necessárias.\n\nParágrafo único. A remessa dos autos far-se-á sem prejuízo de diligências complementares:\n\nI - necessárias ou úteis à plena elucidação do fato, cujo resultado deverá ser encaminhado ao juízo competente até 3 (três) dias antes da audiência de instrução e julgamento;\n\nII - necessárias ou úteis à indicação dos bens, direitos e valores de que seja titular o agente, ou que figurem em seu nome, cujo resultado deverá ser encaminhado ao juízo competente até 3 (três) dias antes da audiência de instrução e julgamento."},{"chave":"art-53","sequencia":68,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO III — DO PROCEDIMENTO PENAL","SEÇÃO I — DA INVESTIGAÇÃO"],"titulo":"SEÇÃO I — DA INVESTIGAÇÃO","rotulo":"Art. 53.","conteudo":"Em qualquer fase da persecução criminal relativa aos crimes previstos nesta Lei, são permitidos, além dos previstos em lei, mediante autorização judicial e ouvido o Ministério Público, os seguintes procedimentos investigatórios:\n\nI - a infiltração por agentes de polícia, em tarefas de investigação, constituída pelos órgãos especializados pertinentes;\n\nII - a não-atuação policial sobre os portadores de drogas, seus precursores químicos ou outros produtos utilizados em sua produção, que se encontrem no território brasileiro, com a finalidade de identificar e responsabilizar maior número de integrantes de operações de tráfico e distribuição, sem prejuízo da ação penal cabível.\n\nParágrafo único. Na hipótese do inciso II deste artigo, a autorização será concedida desde que sejam conhecidos o itinerário provável e a identificação dos agentes do delito ou de colaboradores."},{"chave":"art-54","sequencia":69,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO III — DO PROCEDIMENTO PENAL","SEÇÃO II — DA INSTRUÇÃO CRIMINAL"],"titulo":"SEÇÃO II — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 54.","conteudo":"Recebidos em juízo os autos do inquérito policial, de Comissão Parlamentar de Inquérito ou peças de informação, dar-se-á vista ao Ministério Público para, no prazo de 10 (dez) dias, adotar uma das seguintes providências:\n\nI - requerer o arquivamento;\n\nII - requisitar as diligências que entender necessárias;\n\nIII - oferecer denúncia, arrolar até 5 (cinco) testemunhas e requerer as demais provas que entender pertinentes."},{"chave":"art-55","sequencia":70,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO III — DO PROCEDIMENTO PENAL","SEÇÃO II — DA INSTRUÇÃO CRIMINAL"],"titulo":"SEÇÃO II — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 55.","conteudo":"Oferecida a denúncia, o juiz ordenará a notificação do acusado para oferecer defesa prévia, por escrito, no prazo de 10 (dez) dias.\n\n§ 1º Na resposta, consistente em defesa preliminar e exceções, o acusado poderá argüir preliminares e invocar todas as razões de defesa, oferecer documentos e justificações, especificar as provas que pretende produzir e, até o número de 5 (cinco), arrolar testemunhas.\n\n§ 2º As exceções serão processadas em apartado, nos termos dos arts. 95 a 113 do Decreto-Lei nº 3.689, de 3 de outubro de 1941 - Código de Processo Penal.\n\n§ 3º Se a resposta não for apresentada no prazo, o juiz nomeará defensor para oferecê-la em 10 (dez) dias, concedendo-lhe vista dos autos no ato de nomeação.\n\n§ 4º Apresentada a defesa, o juiz decidirá em 5 (cinco) dias.\n\n§ 5º Se entender imprescindível, o juiz, no prazo máximo de 10 (dez) dias, determinará a apresentação do preso, realização de diligências, exames e perícias."},{"chave":"art-56","sequencia":71,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO III — DO PROCEDIMENTO PENAL","SEÇÃO II — DA INSTRUÇÃO CRIMINAL"],"titulo":"SEÇÃO II — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 56.","conteudo":"Recebida a denúncia, o juiz designará dia e hora para a audiência de instrução e julgamento, ordenará a citação pessoal do acusado, a intimação do Ministério Público, do assistente, se for o caso, e requisitará os laudos periciais.\n\n§ 1º Tratando-se de condutas tipificadas como infração do disposto nos arts. 33, caput e § 1º, e 34 a 37 desta Lei, o juiz, ao receber a denúncia, poderá decretar o afastamento cautelar do denunciado de suas atividades, se for funcionário público, comunicando ao órgão respectivo.\n\n§ 2º A audiência a que se refere o caput deste artigo será realizada dentro dos 30 (trinta) dias seguintes ao recebimento da denúncia, salvo se determinada a realização de avaliação para atestar dependência de drogas, quando se realizará em 90 (noventa) dias."},{"chave":"art-57","sequencia":72,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO III — DO PROCEDIMENTO PENAL","SEÇÃO II — DA INSTRUÇÃO CRIMINAL"],"titulo":"SEÇÃO II — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 57.","conteudo":"Na audiência de instrução e julgamento, após o interrogatório do acusado e a inquirição das testemunhas, será dada a palavra, sucessivamente, ao representante do Ministério Público e ao defensor do acusado, para sustentação oral, pelo prazo de 20 (vinte) minutos para cada um, prorrogável por mais 10 (dez), a critério do juiz.\n\nParágrafo único. Após proceder ao interrogatório, o juiz indagará das partes se restou algum fato para ser esclarecido, formulando as perguntas correspondentes se o entender pertinente e relevante."},{"chave":"art-58","sequencia":73,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO III — DO PROCEDIMENTO PENAL","SEÇÃO II — DA INSTRUÇÃO CRIMINAL"],"titulo":"SEÇÃO II — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 58.","conteudo":"Encerrados os debates, proferirá o juiz sentença de imediato, ou o fará em 10 (dez) dias, ordenando que os autos para isso lhe sejam conclusos.\n\n§ 1º (Revogado pela Lei nº 12.961, de 2014)\n\n§ 2º (Revogado pela Lei nº 12.961, de 2014)"},{"chave":"art-59","sequencia":74,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO III — DO PROCEDIMENTO PENAL","SEÇÃO II — DA INSTRUÇÃO CRIMINAL"],"titulo":"SEÇÃO II — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 59.","conteudo":"Nos crimes previstos nos arts. 33, caput e § 1º, e 34 a 37 desta Lei, o réu não poderá apelar sem recolher-se à prisão, salvo se for primário e de bons antecedentes, assim reconhecido na sentença condenatória."},{"chave":"art-60","sequencia":75,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO"],"titulo":"CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO","rotulo":"Art. 60.","conteudo":"O juiz, a requerimento do Ministério Público ou do assistente de acusação, ou mediante representação da autoridade de polícia judiciária, poderá decretar, no curso do inquérito ou da ação penal, a apreensão e outras medidas assecuratórias nos casos em que haja suspeita de que os bens, direitos ou valores sejam produto do crime ou constituam proveito dos crimes previstos nesta Lei, procedendo-se na forma dos arts. 125 e seguintes do Decreto-Lei nº 3.689, de 3 de outubro de 1941 - Código de Processo Penal. (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 1º (Revogado). (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 2º (Revogado). (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 3º Na hipótese do art. 366 do Decreto-Lei nº 3.689, de 3 de outubro de 1941 - Código de Processo Penal, o juiz poderá determinar a prática de atos necessários à conservação dos bens, direitos ou valores. (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 4º A ordem de apreensão ou sequestro de bens, direitos ou valores poderá ser suspensa pelo juiz, ouvido o Ministério Público, quando a sua execução imediata puder comprometer as investigações. (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 5º Decretadas quaisquer das medidas previstas no caput deste artigo, o juiz facultará ao acusado que, no prazo de 5 (cinco) dias, apresente provas, ou requeira a produção delas, acerca da origem lícita do bem ou do valor objeto da decisão, exceto no caso de veículo apreendido em transporte de droga ilícita. (Incluído pela Lei nº 14.322, de 2022)\n\n§ 6º Provada a origem lícita do bem ou do valor, o juiz decidirá por sua liberação, exceto no caso de veículo apreendido em transporte de droga ilícita, cuja destinação observará o disposto nos arts. 61 e 62 desta Lei, ressalvado o direito de terceiro de boa-fé. (Incluído pela Lei nº 14.322, de 2022)"},{"chave":"art-60-a","sequencia":76,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO"],"titulo":"CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO","rotulo":"Art. 60-A","conteudo":"Se as medidas assecuratórias de que trata o art. 60 desta Lei recaírem sobre moeda estrangeira, títulos, valores mobiliários ou cheques emitidos como ordem de pagamento, será determinada, imediatamente, a sua conversão em moeda nacional. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 1º A moeda estrangeira apreendida em espécie deve ser encaminhada a instituição financeira, ou equiparada, para alienação na forma prevista pelo Conselho Monetário Nacional. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 2º Na hipótese de impossibilidade da alienação a que se refere o § 1º deste artigo, a moeda estrangeira será custodiada pela instituição financeira até decisão sobre o seu destino. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 3º Após a decisão sobre o destino da moeda estrangeira a que se refere o § 2º deste artigo, caso seja verificada a inexistência de valor de mercado, seus espécimes poderão ser destruídos ou doados à representação diplomática do país de origem. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 4º Os valores relativos às apreensões feitas antes da data de entrada em vigor da Medida Provisória nº 885, de 17 de junho de 2019, e que estejam custodiados nas dependências do Banco Central do Brasil devem ser transferidos à Caixa Econômica Federal, no prazo de 360 (trezentos e sessenta) dias, para que se proceda à alienação ou custódia, de acordo com o previsto nesta Lei. (Incluído pela Lei nº 13.886, de 2019)"},{"chave":"art-61","sequencia":77,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO"],"titulo":"CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO","rotulo":"Art. 61.","conteudo":"A apreensão de veículos, embarcações, aeronaves e quaisquer outros meios de transporte e dos maquinários, utensílios, instrumentos e objetos de qualquer natureza utilizados para a prática, habitual ou não, dos crimes definidos nesta Lei será imediatamente comunicada pela autoridade de polícia judiciária responsável pela investigação ao juízo competente. (Redação dada pela Lei nº 14.322, de 2022)\n\n§ 1º O juiz, no prazo de 30 (trinta) dias contado da comunicação de que trata o caput, determinará a alienação dos bens apreendidos, excetuadas as armas, que serão recolhidas na forma da legislação específica. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 2º A alienação será realizada em autos apartados, dos quais constará a exposição sucinta do nexo de instrumentalidade entre o delito e os bens apreendidos, a descrição e especificação dos objetos, as informações sobre quem os tiver sob custódia e o local em que se encontrem. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 3º O juiz determinará a avaliação dos bens apreendidos, que será realizada por oficial de justiça, no prazo de 5 (cinco) dias a contar da autuação, ou, caso sejam necessários conhecimentos especializados, por avaliador nomeado pelo juiz, em prazo não superior a 10 (dez) dias. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 4º Feita a avaliação, o juiz intimará o órgão gestor do Funad, o Ministério Público e o interessado para se manifestarem no prazo de 5 (cinco) dias e, dirimidas eventuais divergências, homologará o valor atribuído aos bens. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 5º (VETADO). (Incluído pela Lei nº 13.840, de 2019)\n\n§ 6º (Revogado). (Redação dada pela Lei nº 13.886, de 2019)\n\n§ 7º (Revogado). (Redação dada pela Lei nº 13.886, de 2019)\n\n§ 8º (Revogado). (Redação dada pela Lei nº 13.886, de 2019)\n\n§ 9º O Ministério Público deve fiscalizar o cumprimento da regra estipulada no § 1º deste artigo. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 10. Aplica-se a todos os tipos de bens confiscados a regra estabelecida no § 1º deste artigo. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 11. Os bens móveis e imóveis devem ser vendidos por meio de hasta pública, preferencialmente por meio eletrônico, assegurada a venda pelo maior lance, por preço não inferior a 50% (cinquenta por cento) do valor da avaliação judicial. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 12. O juiz ordenará às secretarias de fazenda e aos órgãos de registro e controle que efetuem as averbações necessárias, tão logo tenha conhecimento da apreensão. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 13. Na alienação de veículos, embarcações ou aeronaves, a autoridade de trânsito ou o órgão congênere competente para o registro, bem como as secretarias de fazenda, devem proceder à regularização dos bens no prazo de 30 (trinta) dias, ficando o arrematante isento do pagamento de multas, encargos e tributos anteriores, sem prejuízo de execução fiscal em relação ao antigo proprietário. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 14. Eventuais multas, encargos ou tributos pendentes de pagamento não podem ser cobrados do arrematante ou do órgão público alienante como condição para regularização dos bens. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 15. Na hipótese de que trata o § 13 deste artigo, a autoridade de trânsito ou o órgão congênere competente para o registro poderá emitir novos identificadores dos bens. (Incluído pela Lei nº 13.886, de 2019)"},{"chave":"art-62","sequencia":78,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO"],"titulo":"CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO","rotulo":"Art. 62.","conteudo":"Comprovado o interesse público na utilização de quaisquer dos bens de que trata o art. 61, os órgãos de polícia judiciária, militar e rodoviária poderão deles fazer uso, sob sua responsabilidade e com o objetivo de sua conservação, mediante autorização judicial, ouvido o Ministério Público e garantida a prévia avaliação dos respectivos bens. (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 1º (Revogado). (Redação dada pela Lei nº 13.886, de 2019)\n\n§ 1º-A. O juízo deve cientificar o órgão gestor do Funad para que, em 10 (dez) dias, avalie a existência do interesse público mencionado no caput deste artigo e indique o órgão que deve receber o bem. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 1º-B. Têm prioridade, para os fins do § 1º-A deste artigo, os órgãos de segurança pública que participaram das ações de investigação ou repressão ao crime que deu causa à medida. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 2º A autorização judicial de uso de bens deverá conter a descrição do bem e a respectiva avaliação e indicar o órgão responsável por sua utilização. (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 3º O órgão responsável pela utilização do bem deverá enviar ao juiz periodicamente, ou a qualquer momento quando por este solicitado, informações sobre seu estado de conservação. (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 4º Quando a autorização judicial recair sobre veículos, embarcações ou aeronaves, o juiz ordenará à autoridade ou ao órgão de registro e controle a expedição de certificado provisório de registro e licenciamento em favor do órgão ao qual tenha deferido o uso ou custódia, ficando este livre do pagamento de multas, encargos e tributos anteriores à decisão de utilização do bem até o trânsito em julgado da decisão que decretar o seu perdimento em favor da União. (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 5º Na hipótese de levantamento, se houver indicação de que os bens utilizados na forma deste artigo sofreram depreciação superior àquela esperada em razão do transcurso do tempo e do uso, poderá o interessado requerer nova avaliação judicial. (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 6º Constatada a depreciação de que trata o § 5º, o ente federado ou a entidade que utilizou o bem indenizará o detentor ou proprietário dos bens. (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 7º (Revogado). (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 8º (Revogado). (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 9º (Revogado). (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 10. (Revogado). (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 11. (Revogado). (Redação dada pela Lei nº 13.840, de 2019)"},{"chave":"art-62-a","sequencia":79,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO"],"titulo":"CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO","rotulo":"Art. 62-A","conteudo":"O depósito, em dinheiro, de valores referentes ao produto da alienação ou a numerários apreendidos ou que tenham sido convertidos deve ser efetuado na Caixa Econômica Federal, por meio de documento de arrecadação destinado a essa finalidade. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 1º Os depósitos a que se refere o caput deste artigo devem ser transferidos, pela Caixa Econômica Federal, para a conta única do Tesouro Nacional, independentemente de qualquer formalidade, no prazo de 24 (vinte e quatro) horas, contado do momento da realização do depósito, onde ficarão à disposição do Funad. (Incluído pela Lei nº 13.886, de 2019)\n\n(Revogado pela Lei nº 14.973, de 2024)\n\n§ 3º Na hipótese de decretação do seu perdimento em favor da União, o valor do depósito será transformado em pagamento definitivo, respeitados os direitos de eventuais lesados e de terceiros de boa-fé. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 4º Os valores devolvidos pela Caixa Econômica Federal, por decisão judicial, devem ser efetuados como anulação de receita do Funad no exercício em que ocorrer a devolução. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 5º A Caixa Econômica Federal deve manter o controle dos valores depositados ou devolvidos. (Incluído pela Lei nº 13.886, de 2019)"},{"chave":"art-63","sequencia":80,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO"],"titulo":"CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO","rotulo":"Art. 63.","conteudo":"Ao proferir a sentença, o juiz decidirá sobre: (Redação dada pela Lei nº 13.840, de 2019)\n\nI - o perdimento do produto, bem, direito ou valor apreendido ou objeto de medidas assecuratórias; e (Incluído pela Lei nº 13.840, de 2019)\n\nII - o levantamento dos valores depositados em conta remunerada e a liberação dos bens utilizados nos termos do art. 62. (Incluído pela Lei nº 13.840, de 2019)\n\n§ 1º Os bens, direitos ou valores apreendidos em decorrência dos crimes tipificados nesta Lei ou objeto de medidas assecuratórias, após decretado seu perdimento em favor da União, serão revertidos diretamente ao Funad. (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 2º O juiz remeterá ao órgão gestor do Funad relação dos bens, direitos e valores declarados perdidos, indicando o local em que se encontram e a entidade ou o órgão em cujo poder estejam, para os fins de sua destinação nos termos da legislação vigente. (Redação dada pela Lei nº 13.840, de 2019)\n\n§ 3º (Revogado ). (Redação dada pela Lei nº 13.886, de 2019)\n\n§ 4º Transitada em julgado a sentença condenatória, o juiz do processo, de ofício ou a requerimento do Ministério Público, remeterá à Senad relação dos bens, direitos e valores declarados perdidos em favor da União, indicando, quanto aos bens, o local em que se encontram e a entidade ou o órgão em cujo poder estejam, para os fins de sua destinação nos termos da legislação vigente.\n\n§ 4º-A. Antes de encaminhar os bens ao órgão gestor do Funad, o juíz deve: (Incluído pela Lei nº 13.886, de 2019)\n\nI – ordenar às secretarias de fazenda e aos órgãos de registro e controle que efetuem as averbações necessárias, caso não tenham sido realizadas quando da apreensão; e (Incluído pela Lei nº 13.886, de 2019)\n\nII – determinar, no caso de imóveis, o registro de propriedade em favor da União no cartório de registro de imóveis competente, nos termos do caput e do parágrafo único do art. 243 da Constituição Federal, afastada a responsabilidade de terceiros prevista no inciso VI do caput do art. 134 da Lei nº 5.172, de 25 de outubro de 1966 (Código Tributário Nacional), bem como determinar à Secretaria de Coordenação e Governança do Patrimônio da União a incorporação e entrega do imóvel, tornando-o livre e desembaraçado de quaisquer ônus para sua destinação. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 5º (VETADO). (Incluído pela Lei nº 13.840, de 2019)\n\n§ 6º Na hipótese do inciso II do caput, decorridos 360 (trezentos e sessenta) dias do trânsito em julgado e do conhecimento da sentença pelo interessado, os bens apreendidos, os que tenham sido objeto de medidas assecuratórias ou os valores depositados que não forem reclamados serão revertidos ao Funad. (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-63-a","sequencia":81,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO"],"titulo":"CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO","rotulo":"Art. 63-A","conteudo":"Nenhum pedido de restituição será conhecido sem o comparecimento pessoal do acusado, podendo o juiz determinar a prática de atos necessários à conservação de bens, direitos ou valores. (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-63-b","sequencia":82,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO"],"titulo":"CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO","rotulo":"Art. 63-B","conteudo":"O juiz determinará a liberação total ou parcial dos bens, direitos e objeto de medidas assecuratórias quando comprovada a licitude de sua origem, mantendo-se a constrição dos bens, direitos e valores necessários e suficientes à reparação dos danos e ao pagamento de prestações pecuniárias, multas e custas decorrentes da infração penal. (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-63-c","sequencia":83,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO"],"titulo":"CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO","rotulo":"Art. 63-C","conteudo":"Compete à Senad, do Ministério da Justiça e Segurança Pública, proceder à destinação dos bens apreendidos e não leiloados em caráter cautelar, cujo perdimento seja decretado em favor da União, por meio das seguintes modalidades: (Incluído pela Lei nº 13.886, de 2019)\n\nI – alienação, mediante: (Incluído pela Lei nº 13.886, de 2019)\n\na) licitação; (Incluído pela Lei nº 13.886, de 2019)\n\nb) doação com encargo a entidades ou órgãos públicos, bem como a comunidades terapêuticas acolhedoras que contribuam para o alcance das finalidades do Funad; ou (Incluído pela Lei nº 13.886, de 2019)\n\nc) venda direta, observado o disposto no inciso II do caput do art. 24 da Lei nº 8.666, de 21 de junho de 1993; (Incluído pela Lei nº 13.886, de 2019)\n\nII – incorporação ao patrimônio de órgão da administração pública, observadas as finalidades do Funad; (Incluído pela Lei nº 13.886, de 2019)\n\nIII – destruição; ou (Incluído pela Lei nº 13.886, de 2019)\n\nIV – inutilização. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 1º A alienação por meio de licitação deve ser realizada na modalidade leilão, para bens móveis e imóveis, independentemente do valor de avaliação, isolado ou global, de bem ou de lotes, assegurada a venda pelo maior lance, por preço não inferior a 50% (cinquenta por cento) do valor da avaliação. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 2º O edital do leilão a que se refere o § 1º deste artigo será amplamente divulgado em jornais de grande circulação e em sítios eletrônicos oficiais, principalmente no Município em que será realizado, dispensada a publicação em diário oficial. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 3º Nas alienações realizadas por meio de sistema eletrônico da administração pública, a publicidade dada pelo sistema substituirá a publicação em diário oficial e em jornais de grande circulação. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 4º Na alienação de imóveis, o arrematante fica livre do pagamento de encargos e tributos anteriores, sem prejuízo de execução fiscal em relação ao antigo proprietário. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 5º Na alienação de veículos, embarcações ou aeronaves deverão ser observadas as disposições dos §§ 13 e 15 do art. 61 desta Lei. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 6º Aplica-se às alienações de que trata este artigo a proibição relativa à cobrança de multas, encargos ou tributos prevista no § 14 do art. 61 desta Lei. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 7º A Senad, do Ministério da Justiça e Segurança Pública, pode celebrar convênios ou instrumentos congêneres com órgãos e entidades da União, dos Estados, do Distrito Federal ou dos Municípios, bem como com comunidades terapêuticas acolhedoras, a fim de dar imediato cumprimento ao estabelecido neste artigo. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 8º Observados os procedimentos licitatórios previstos em lei, fica autorizada a contratação da iniciativa privada para a execução das ações de avaliação, de administração e de alienação dos bens a que se refere esta Lei. (Incluído pela Lei nº 13.886, de 2019)"},{"chave":"art-63-d","sequencia":84,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO"],"titulo":"CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO","rotulo":"Art. 63-D","conteudo":"Compete ao Ministério da Justiça e Segurança Pública regulamentar os procedimentos relativos à administração, à preservação e à destinação dos recursos provenientes de delitos e atos ilícitos e estabelecer os valores abaixo dos quais se deve proceder à sua destruição ou inutilização. (Incluído pela Lei nº 13.886, de 2019)"},{"chave":"art-63-e","sequencia":85,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO"],"titulo":"CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO","rotulo":"Art. 63-E","conteudo":"O produto da alienação dos bens apreendidos ou confiscados será revertido integralmente ao Funad, nos termos do parágrafo único do art. 243 da Constituição Federal, vedada a sub-rogação sobre o valor da arrematação para saldar eventuais multas, encargos ou tributos pendentes de pagamento. (Incluído pela Lei nº 13.886, de 2019)\n\nParágrafo único. O disposto no caput deste artigo não prejudica o ajuizamento de execução fiscal em relação aos antigos devedores. (Incluído pela Lei nº 13.886, de 2019)"},{"chave":"art-63-f","sequencia":86,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO"],"titulo":"CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO","rotulo":"Art. 63-F","conteudo":"Na hipótese de condenação por infrações às quais esta Lei comine pena máxima superior a 6 (seis) anos de reclusão, poderá ser decretada a perda, como produto ou proveito do crime, dos bens correspondentes à diferença entre o valor do patrimônio do condenado e aquele compatível com o seu rendimento lícito. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 1º A decretação da perda prevista no caput deste artigo fica condicionada à existência de elementos probatórios que indiquem conduta criminosa habitual, reiterada ou profissional do condenado ou sua vinculação a organização criminosa. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 2º Para efeito da perda prevista no caput deste artigo, entende-se por patrimônio do condenado todos os bens: (Incluído pela Lei nº 13.886, de 2019)\n\nI – de sua titularidade, ou sobre os quais tenha domínio e benefício direto ou indireto, na data da infração penal, ou recebidos posteriormente; e (Incluído pela Lei nº 13.886, de 2019)\n\nII – transferidos a terceiros a título gratuito ou mediante contraprestação irrisória, a partir do início da atividade criminal. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 3º O condenado poderá demonstrar a inexistência da incompatibilidade ou a procedência lícita do patrimônio. (Incluído pela Lei nº 13.886, de 2019)"},{"chave":"art-64","sequencia":87,"caminho":["LEI DE DROGAS","TÍTULO IV — DA REPRESSÃO À PRODUÇÃO NÃO AUTORIZADA E AO TRÁFICO ILÍCITO DE DROGAS","CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO"],"titulo":"CAPÍTULO IV — DA APREENSÃO, ARRECADAÇÃO E DESTINAÇÃO DE BENS DO ACUSADO","rotulo":"Art. 64.","conteudo":"A União, por intermédio da Senad, poderá firmar convênio com os Estados, com o Distrito Federal e com organismos orientados para a prevenção do uso indevido de drogas, a atenção e a reinserção social de usuários ou dependentes e a atuação na repressão à produção não autorizada e ao tráfico ilícito de drogas, com vistas na liberação de equipamentos e de recursos por ela arrecadados, para a implantação e execução de programas relacionados à questão das drogas."},{"chave":"art-65","sequencia":88,"caminho":["LEI DE DROGAS","TÍTULO V — DA COOPERAÇÃO INTERNACIONAL"],"titulo":"TÍTULO V — DA COOPERAÇÃO INTERNACIONAL","rotulo":"Art. 65.","conteudo":"De conformidade com os princípios da não-intervenção em assuntos internos, da igualdade jurídica e do respeito à integridade territorial dos Estados e às leis e aos regulamentos nacionais em vigor, e observado o espírito das Convenções das Nações Unidas e outros instrumentos jurídicos internacionais relacionados à questão das drogas, de que o Brasil é parte, o governo brasileiro prestará, quando solicitado, cooperação a outros países e organismos internacionais e, quando necessário, deles solicitará a colaboração, nas áreas de:\n\nI - intercâmbio de informações sobre legislações, experiências, projetos e programas voltados para atividades de prevenção do uso indevido, de atenção e de reinserção social de usuários e dependentes de drogas;\n\nII - intercâmbio de inteligência policial sobre produção e tráfico de drogas e delitos conexos, em especial o tráfico de armas, a lavagem de dinheiro e o desvio de precursores químicos;\n\nIII - intercâmbio de informações policiais e judiciais sobre produtores e traficantes de drogas e seus precursores químicos."},{"chave":"art-65-a","sequencia":89,"caminho":["LEI DE DROGAS","TÍTULO V-A — DO FINANCIAMENTO DAS POLÍTICAS SOBRE DROGAS"],"titulo":"TÍTULO V-A — DO FINANCIAMENTO DAS POLÍTICAS SOBRE DROGAS","rotulo":"Art. 65-A","conteudo":"(VETADO). (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-66","sequencia":90,"caminho":["LEI DE DROGAS","TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS"],"titulo":"TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS","rotulo":"Art. 66.","conteudo":"Para fins do disposto no parágrafo único do art. 1º desta Lei, até que seja atualizada a terminologia da lista mencionada no preceito, denominam-se drogas substâncias entorpecentes, psicotrópicas, precursoras e outras sob controle especial, da Portaria SVS/MS nº 344, de 12 de maio de 1998."},{"chave":"art-67","sequencia":91,"caminho":["LEI DE DROGAS","TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS"],"titulo":"TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS","rotulo":"Art. 67.","conteudo":"A liberação dos recursos previstos na Lei nº 7.560, de 19 de dezembro de 1986, em favor de Estados e do Distrito Federal, dependerá de sua adesão e respeito às diretrizes básicas contidas nos convênios firmados e do fornecimento de dados necessários à atualização do sistema previsto no art. 17 desta Lei, pelas respectivas polícias judiciárias."},{"chave":"art-67-a","sequencia":92,"caminho":["LEI DE DROGAS","TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS"],"titulo":"TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS","rotulo":"Art. 67-A","conteudo":"Os gestores e entidades que recebam recursos públicos para execução das políticas sobre drogas deverão garantir o acesso às suas instalações, à documentação e a todos os elementos necessários à efetiva fiscalização pelos órgãos competentes. (Incluído pela Lei nº 13.840, de 2019)"},{"chave":"art-68","sequencia":93,"caminho":["LEI DE DROGAS","TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS"],"titulo":"TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS","rotulo":"Art. 68.","conteudo":"A União, os Estados, o Distrito Federal e os Municípios poderão criar estímulos fiscais e outros, destinados às pessoas físicas e jurídicas que colaborem na prevenção do uso indevido de drogas, atenção e reinserção social de usuários e dependentes e na repressão da produção não autorizada e do tráfico ilícito de drogas."},{"chave":"art-69","sequencia":94,"caminho":["LEI DE DROGAS","TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS"],"titulo":"TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS","rotulo":"Art. 69.","conteudo":"No caso de falência ou liquidação extrajudicial de empresas ou estabelecimentos hospitalares, de pesquisa, de ensino, ou congêneres, assim como nos serviços de saúde que produzirem, venderem, adquirirem, consumirem, prescreverem ou fornecerem drogas ou de qualquer outro em que existam essas substâncias ou produtos, incumbe ao juízo perante o qual tramite o feito:\n\nI - determinar, imediatamente à ciência da falência ou liquidação, sejam lacradas suas instalações;\n\nII - ordenar à autoridade sanitária competente a urgente adoção das medidas necessárias ao recebimento e guarda, em depósito, das drogas arrecadadas;\n\nIII - dar ciência ao órgão do Ministério Público, para acompanhar o feito.\n\n§ 1º Da licitação para alienação de substâncias ou produtos não proscritos referidos no inciso II do caput deste artigo, só podem participar pessoas jurídicas regularmente habilitadas na área de saúde ou de pesquisa científica que comprovem a destinação lícita a ser dada ao produto a ser arrematado.\n\n§ 2º Ressalvada a hipótese de que trata o § 3º deste artigo, o produto não arrematado será, ato contínuo à hasta pública, destruído pela autoridade sanitária, na presença dos Conselhos Estaduais sobre Drogas e do Ministério Público.\n\n§ 3º Figurando entre o praceado e não arrematadas especialidades farmacêuticas em condições de emprego terapêutico, ficarão elas depositadas sob a guarda do Ministério da Saúde, que as destinará à rede pública de saúde."},{"chave":"art-70","sequencia":95,"caminho":["LEI DE DROGAS","TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS"],"titulo":"TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS","rotulo":"Art. 70.","conteudo":"O processo e o julgamento dos crimes previstos nos arts. 33 a 37 desta Lei, se caracterizado ilícito transnacional, são da competência da Justiça Federal.\n\nParágrafo único. Os crimes praticados nos Municípios que não sejam sede de vara federal serão processados e julgados na vara federal da circunscrição respectiva."},{"chave":"art-71","sequencia":96,"caminho":["LEI DE DROGAS","TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS"],"titulo":"TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS","rotulo":"Art. 71.","conteudo":"(VETADO)"},{"chave":"art-72","sequencia":97,"caminho":["LEI DE DROGAS","TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS"],"titulo":"TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS","rotulo":"Art. 72.","conteudo":"Encerrado o processo criminal ou arquivado o inquérito policial, o juiz, de ofício, mediante representação da autoridade de polícia judiciária, ou a requerimento do Ministério Público, determinará a destruição das amostras guardadas para contraprova, certificando nos autos. (Redação dada pela Lei nº 13.840, de 2019)"},{"chave":"art-73","sequencia":98,"caminho":["LEI DE DROGAS","TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS"],"titulo":"TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS","rotulo":"Art. 73.","conteudo":"A União poderá estabelecer convênios com os Estados e o com o Distrito Federal, visando à prevenção e repressão do tráfico ilícito e do uso indevido de drogas, e com os Municípios, com o objetivo de prevenir o uso indevido delas e de possibilitar a atenção e reinserção social de usuários e dependentes de drogas. (Redação dada pela Lei nº 12.219, de 2010)"},{"chave":"art-74","sequencia":99,"caminho":["LEI DE DROGAS","TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS"],"titulo":"TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS","rotulo":"Art. 74.","conteudo":"Esta Lei entra em vigor 45 (quarenta e cinco) dias após a sua publicação."},{"chave":"art-75","sequencia":100,"caminho":["LEI DE DROGAS","TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS"],"titulo":"TÍTULO VI — DISPOSIÇÕES FINAIS E TRANSITÓRIAS","rotulo":"Art. 75.","conteudo":"Revogam-se a Lei nº 6.368, de 21 de outubro de 1976, e a Lei nº 10.409, de 11 de janeiro de 2002."}]$dados$::jsonb)
    as item(chave text, sequencia integer, caminho text[], titulo text, rotulo text, conteudo text);

